  ('sovietski-tsar-superheavy-machine', 'Armored Ammo-Drum (1; back)', 150, NULL, 7),
  ('sovietski-tsar-superheavy-machine', 'Weapon Connector Appendage', 95, 'Destroyed, the Empress Cannon must be carried by hand or left behind.', 8),
