  ('sovietski-tsar-superheavy-machine', 'Short-Range Missile Launcher (1; left shoulder)', 80, 'Small target: Called Shot only, -3 to strike.', 11),
  ('sovietski-tsar-superheavy-machine', 'Head', 150, '+80 from the exterior helmet. Small target: Called Shot only, and shielded by the rail gun and shoulder plating on one side and the missile launcher on the other, so -4 to strike. Destroying the head kills the character.', 12),
  ('sovietski-tsar-superheavy-machine', 'Main Body', 740, 'Armor plating is bolted on as built, so no further armor can be added. Depleted, the body is destroyed but life support keeps the brain alive up to 36 hours for recovery and a new body; 125 points below zero destroys the cyborg beyond recovery.', 13),
  ('sovietski-cyborg-falcon-or-hawk', 'Wings (2)', 10, 'Each. Small target: Called Shot only, -3 to strike a perched bird, -5 against a small part of one in flight.', 1),
  ('sovietski-cyborg-falcon-or-hawk', 'Legs and Talons (2)', 15, 'Each. Small target: Called Shot only, -3 to strike a perched bird, -5 against a small part of one in flight.', 2),
