INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('sovietski-tsar-superheavy-machine', 1, 'S-9001 Rail Auto-Cannon, the Empress Cannon (1; handheld)', '1D6x10+6 M.D. per single high-explosive round', 1, '4,000 feet (1,219 m)', 'Single shots only; no bursts.', '200 rounds in an internal magazine; a trained technician reloads the special drum in five minutes.', NULL, 'Anti-armor and anti-cyborg; also assault and anti-monster. An 11 foot (3.4 m) cannon fired like an outsized rifle; its heavy slugs can stagger large cyborgs and rock armored vehicles, so the Tsar often fights beside tanks and other armored vehicles. Stowed behind the left shoulder, barrel down, held by four clamps on the back.'),
  ('sovietski-tsar-superheavy-machine', 2, 'Rail Gun Shoulder Turret (1; right)', '5D6 M.D. per 10 round burst', 1, '2,000 feet (610 m)', 'Each burst counts as one melee attack.', '1,000 rounds in an internal drum, enough for 100 bursts.', NULL, 'Assault and anti-personnel; also defense. A light turret over the right shoulder that turns 360 degrees with a 45 degree arc up and down.'),
  ('sovietski-tsar-superheavy-machine', 3, 'Short-Range Missile Launcher (1; left shoulder)', 'Varies with missile type; typically medium high explosive, 2D6x10 M.D. to everything in a 15 foot (4.6 m) radius', 1, 'Five miles (8 km)', 'One at a time or in volleys of 2 or 4.', 'Four missiles.', NULL, 'Anti-aircraft, for flying cyborgs and monsters; also anti-monster. A four tube launcher over the left shoulder.'),
  ('sovietski-tsar-superheavy-machine', 4, 'Forearm Ion Blasters (2)', '5D6 M.D. per single blast; 1D6x10 M.D. when both fire together at one target', 1, '1,000 feet (305 m)', 'Each single or dual blast counts as one melee attack.', 'Effectively unlimited; tied to the cyborg''s nuclear power supply.', NULL, 'Defense. A low-profile blaster in each forearm; no dual blast while the Empress Cannon is in use.'),
  ('sovietski-cyborg-falcon-or-hawk', 1, 'Vibro-Talons (2)', '1D4 M.D. per talon strike, +2 M.D. on a diving attack', 1, 'Melee.', NULL, NULL, NULL, 'Close combat. A set of Vibro-Talons on each foot for slashing and clawing.'),
  ('sovietski-cyborg-falcon-or-hawk', 2, 'Deployable Explosive Charges (2)', '5D6 M.D. to everything in a 3 foot (0.9 m) radius', 1, 'Melee or dropped; the bird must be on or above the target.', 'One at a time or both together.', 'Two; one per leg.', NULL, 'Strategic demolition. An impact-fused charge in a small pouch held in each talon. Risky: it goes off if dropped, with a 50% chance whenever a predator, monster, hunter or enemy attacks the bird, and the bird lets go when it opens its talons to fight, so it is used only in remote areas or emergencies. The same carry can safely drop a message, a radio, 1-2 E-Clips, flares, a tool, water, a first aid kit or similar small items.'),
  ('sovietski-cyborg-steppe-eagle', 1, 'Vibro-Talons (2)', '2D4 M.D. per talon strike, +4 M.D. on a diving attack', 1, 'Melee.', NULL, NULL, NULL, 'Close combat. A set of Vibro-Talons on each foot for slashing and clawing.'),
  ('sovietski-cyborg-steppe-eagle', 2, 'Deployable Explosive Charges (2)', '5D6 M.D. to everything in a 3 foot (0.9 m) radius', 1, 'Melee or dropped; the bird must be on or above the target.', 'One at a time or both together.', 'Two; one per leg.', NULL, 'Strategic demolition. An impact-fused charge in a small pouch held in each talon. Risky: it goes off if dropped, with a 50% chance whenever a predator, monster, hunter or enemy attacks the bird, and the bird lets go when it opens its talons to fight, so it is used only in remote areas or emergencies. The same carry can safely drop a message, a radio, 1-2 E-Clips, flares, a tool, water, a first aid kit or similar small items.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 3 machines are in' AS assertion, count(*) AS got, 3 AS want
  FROM vehicles WHERE slug IN ('sovietski-tsar-superheavy-machine', 'sovietski-cyborg-falcon-or-hawk', 'sovietski-cyborg-steppe-eagle');
SELECT 'their 21 locations are in' AS assertion, count(*) AS got, 21 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('sovietski-tsar-superheavy-machine', 'sovietski-cyborg-falcon-or-hawk', 'sovietski-cyborg-steppe-eagle');
SELECT 'their 8 weapon entries are in' AS assertion, count(*) AS got, 8 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('sovietski-tsar-superheavy-machine', 'sovietski-cyborg-falcon-or-hawk', 'sovietski-cyborg-steppe-eagle');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('sovietski-tsar-superheavy-machine', 'sovietski-cyborg-falcon-or-hawk', 'sovietski-cyborg-steppe-eagle') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

